ALTER POLICY market_scope_photos ON public.inspection_photos USING ((EXISTS (SELECT 1 FROM public.inspections i WHERE i.id=inspection_photos.inspection_id AND public.user_has_market(auth.uid(),i.market))) OR (photo_stage='marketing' AND public.advisor_can_read_marketing_photo(inspection_id)));
CREATE OR REPLACE FUNCTION public.advisor_can_read_marketing_object(p_bucket text,p_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p_bucket='inspection-photos' AND EXISTS (SELECT 1 FROM public.inspection_photos p JOIN public.inspection_sections sec ON sec.id=p.inspection_section_id AND sec.inspection_id=p.inspection_id WHERE p.storage_bucket=p_bucket AND p.storage_path=p_path AND p.photo_stage='marketing' AND sec.section_key='marketing_photos' AND public.advisor_can_read_marketing_photo(p.inspection_id)); $$;
REVOKE ALL ON FUNCTION public.advisor_can_read_marketing_object(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.advisor_can_read_marketing_object(text,text) TO authenticated,service_role;
ALTER POLICY "Advisor downloads assigned property marketing photos" ON storage.objects USING (public.advisor_can_read_marketing_object(bucket_id,name));